let reqExplorer={root:null,stories:false,closed:new Set(),zoom:1};
showRequirementTree=function(id,withStories=false){reqExplorer={root:id||null,stories:withStories,closed:new Set(),zoom:1};drawReqExplorer();};
function toggleReqExplorer(id){reqExplorer.closed.has(id)?reqExplorer.closed.delete(id):reqExplorer.closed.add(id);drawReqExplorer();}
function zoomReqExplorer(n){reqExplorer.zoom=n===0?1:Math.max(.5,Math.min(1.5,reqExplorer.zoom+n));drawReqExplorer();}
function drawReqExplorer(){const state=reqExplorer,roots=state.root?hierarchyRows().filter(r=>r.id===state.root):childRequirements(),box=document.getElementById('modal');function outline(r){const children=childRequirements(r.id),closed=state.closed.has(r.id);return '<li><button onclick="toggleReqExplorer(\''+r.id+'\')" aria-expanded="'+!closed+'">'+(children.length?(closed?'▸ ':'▾ '):'· ')+esc(r.story)+'</button>'+(!closed&&children.length?'<ul>'+children.map(outline).join('')+'</ul>':'')+'</li>';}function card(r,path=[]){if(path.includes(r.id))return '';const children=childRequirements(r.id),closed=state.closed.has(r.id);return '<li><div class="org-card"><div class="org-card-title"><small>'+esc(r.id)+'</small><strong>'+esc(r.story)+'</strong></div><div class="org-card-meta">'+badge(r.status||'Draft')+'<span>'+Number(r.priorityPoints||0)+' points</span></div><p>'+esc(r.module||'General')+'</p>'+(state.stories?'<div class="org-story"><b>User story</b><p>'+esc(r.userStory||'Not written yet')+'</p><b>Acceptance criteria</b><p>'+esc(r.ac||'Not defined yet')+'</p></div>':'')+(children.length?'<button onclick="toggleReqExplorer(\''+r.id+'\')" aria-expanded="'+!closed+'">'+(closed?'Expand':'Collapse')+' · '+children.length+'</button>':'')+'</div>'+(!closed&&children.length?'<ul>'+children.map(c=>card(c,[...path,r.id])).join('')+'</ul>':'')+'</li>';}
box.className='org-explorer-dialog';box.innerHTML='<div class="org-toolbar"><div><h2>Requirement tree</h2><span>Explore parent requirements and their children</span></div><div class="actions"><button onclick="reqExplorer.closed.clear();drawReqExplorer()">Expand all</button><button onclick="zoomReqExplorer(-.1)" aria-label="Zoom out">−</button><span>'+Math.round(state.zoom*100)+'%</span><button onclick="zoomReqExplorer(.1)" aria-label="Zoom in">+</button><button onclick="zoomReqExplorer(0)">Reset</button><button aria-label="Close tree" onclick="document.getElementById(\'modal\').close()">×</button></div></div><div class="org-layout"><section class="org-outline"><h3>Tree view</h3><ul>'+roots.map(outline).join('')+'</ul></section><div class="org-canvas" tabindex="0" aria-label="Scrollable requirement hierarchy"><div class="org-chart" style="zoom:'+state.zoom+'"><ul>'+roots.map(r=>card(r)).join('')+'</ul>'+(!roots.length?'<p>No requirements yet.</p>':'')+'</div></div></div>';if(!box.open)box.showModal();}
